mkitem!{declare_lint ! { #[doc = " The `async_fn_in_trait` lint detects use of `async fn` in the"] #[doc = " definition of a publicly-reachable trait."] #[doc = ""] #[doc = " ### Example"] #[doc = ""] #[doc = " ```rust"] #[doc = " pub trait Trait {"] #[doc = "     async fn method(&self);"] #[doc = " }"] #[doc = " # fn main() {}"] #[doc = " ```"] #[doc = ""] #[doc = " {{produces}}"] #[doc = ""] #[doc = " ### Explanation"] #[doc = ""] #[doc = " When `async fn` is used in a trait definition, the trait does not"] #[doc = " promise that the opaque [`Future`] returned by the associated function"] #[doc = " or method will implement any [auto traits] such as [`Send`]. This may"] #[doc = " be surprising and may make the associated functions or methods on the"] #[doc = " trait less useful than intended. On traits exposed publicly from a"] #[doc = " crate, this may affect downstream crates whose authors cannot alter"] #[doc = " the trait definition."] #[doc = ""] #[doc = " For example, this code is invalid:"] #[doc = ""] #[doc = " ```rust,compile_fail"] #[doc = " pub trait Trait {"] #[doc = "     async fn method(&self) {}"] #[doc = " }"] #[doc = ""] #[doc = " fn test<T: Trait>(x: T) {"] #[doc = "     fn spawn<T: Send>(_: T) {}"] #[doc = "     spawn(x.method()); // Not OK."] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " This lint exists to warn authors of publicly-reachable traits that"] #[doc = " they may want to consider desugaring the `async fn` to a normal `fn`"] #[doc = " that returns an opaque `impl Future<..> + Send` type."] #[doc = ""] #[doc = " For example, instead of:"] #[doc = ""] #[doc = " ```rust"] #[doc = " pub trait Trait {"] #[doc = "     async fn method(&self) {}"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " The author of the trait may want to write:"] #[doc = ""] #[doc = ""] #[doc = " ```rust"] #[doc = " use core::future::Future;"] #[doc = " pub trait Trait {"] #[doc = "     fn method(&self) -> impl Future<Output = ()> + Send { async {} }"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " This still allows the use of `async fn` within impls of the trait."] #[doc = " However, it also means that the trait will never be compatible with"] #[doc = " impls where the returned [`Future`] of the method does not implement"] #[doc = " `Send`."] #[doc = ""] #[doc = " Conversely, if the trait is used only locally, if it is never used in"] #[doc = " generic functions, or if it is only used in single-threaded contexts"] #[doc = " that do not care whether the returned [`Future`] implements [`Send`],"] #[doc = " then the lint may be suppressed."] #[doc = ""] #[doc = " [`Future`]: https://doc.rust-lang.org/core/future/trait.Future.html"] #[doc = " [`Send`]: https://doc.rust-lang.org/core/marker/trait.Send.html"] #[doc = " [auto traits]: https://doc.rust-lang.org/reference/special-types-and-traits.html#auto-traits"] pub ASYNC_FN_IN_TRAIT , Warn , "use of `async fn` in definition of a publicly-reachable trait" }}
